PuntoVentaReferencia, IDTalla, UsuarioTrCr, ";				$sql_codesp  .= "FechaTrCr) VALUES ('$dcodesp', '$r_ref->IDPuntoVentaReferencia', '$idtalla', '$Nombre_Usuario', now()) ";				$query_codesp = db_query( $sql_codesp );								insertlog($ID_Usuario,"CodificacionEspecifica",$dcodesp,"Insertar",$sql_codesp);			}					}//end if($frm['IdCodigo$i'] <> "")			}//end for($i = 1; $i < count($frm); $i++ )	}//end function insert_tallas($id, $frm)function print_form_fotos($id,$numfotos){Global $numfotos;?><table border=1 cellpadding=1 cellspacing=0 bordercolor=#9DAAC6 align=center style="border-collapse: collapse">	<tr>		<td class=titlemedium bgcolor=#9daac6>Agregar Tallas - <?=get_field("TipoTalla","Descripcion","IDTipoTalla",$id)?></td>	</tr>	<tr>		<td>			<table width=450 border=0 cellspacing=1 cellpadding=1 class=texto>				<tr class=row2>					<td colspan="2">						<FORM name="frm" method="post" enctype="multipart/form-data" action='<?=$PHP_SELF?>' onsubmit="return validar(this)">							<table width=100% border=0>								<tr>									<td id="field" colspan=2 bgcolor=#e7ebef>										<input type="button" onclick="addRow()" value="agregar">										<input type="button" onclick="delRow()" value="remover">									</td>								</tr>								<tr bgcolor=#e7ebef>									<td colspan="4" width="816">										<table class="texto"  border="0" cellspacing="1" cellpadding="0" id=table1>											<tr bgcolor="#dfe3e7">												<td width="3%" align="center"></td>												<td width="11%" align="center"></td>											</tr>											<tbody bgcolor=#e7ebef>											</tbody>										</table>									</td>								</tr>							</table>							<input type=hidden name=id value="<?=$id?>">							<input type=hidden name=UsuarioTrCr value="">							<input type=hidden name=FechaTrCr value="">							<INPUT TYPE="hidden" NAME="numfotos" VALUE=<?=$numfotos?>>							<input type="submit" name="submit" value="Continuar">						</FORM>					</td>				